const ingestReportRows = `-- name: IngestReportRows :many
SELECT st.id AS student_db_id,
    st.student_id,
    st.name,
    s.id AS submission_id,
    s.page_count,
    s.original_filename,
    (SELECT count(*) FROM answer_pages ap
        JOIN answers a ON a.id = ap.answer_id
        WHERE a.assessment_id = $1 AND a.student_id = st.id) AS mapped_pages
FROM students st
LEFT JOIN submissions s
    ON s.assessment_id = $1 AND s.student_id = st.id AND s.superseded_by IS NULL AND s.retracted_at IS NULL AND s.problem_id IS NULL
WHERE st.withdrawn_at IS NULL
ORDER BY st.student_id
`

type IngestReportRowsRow struct {
	StudentDbID      int64       `json:"student_db_id"`
	StudentID        string      `json:"student_id"`
	Name             string      `json:"name"`
	SubmissionID     pgtype.Int8 `json:"submission_id"`
	PageCount        pgtype.Int4 `json:"page_count"`
	OriginalFilename pgtype.Text `json:"original_filename"`
	MappedPages      int64       `json:"mapped_pages"`
}

func (q *Queries) IngestReportRows(ctx context.Context, assessmentID int64) ([]IngestReportRowsRow, error) {
	rows, err := q.db.Query(ctx, ingestReportRows, assessmentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []IngestReportRowsRow
	for rows.Next() {
		var i IngestReportRowsRow
		if err := rows.Scan(
			&i.StudentDbID,
			&i.StudentID,
			&i.Name,
			&i.SubmissionID,
			&i.PageCount,
			&i.OriginalFilename,
			&i.MappedPages,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

