const reclassifyQuarantine = `-- name: ReclassifyQuarantine :execrows
UPDATE upload_quarantine
SET reason = $2
WHERE id = $1 AND resolved_at IS NULL
`

type ReclassifyQuarantineParams struct {
	ID     int64  `json:"id"`
	Reason string `json:"reason"`
}

func (q *Queries) ReclassifyQuarantine(ctx context.Context, arg ReclassifyQuarantineParams) (int64, error) {
	result, err := q.db.Exec(ctx, reclassifyQuarantine, arg.ID, arg.Reason)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const removeAnswerFlag = `-- name: RemoveAnswerFlag :exec
UPDATE answers SET flags = array_remove(flags, $2::text), updated_at = now()
WHERE id = $1 AND $2::text = ANY (flags)
`

type RemoveAnswerFlagParams struct {
	ID   int64  `json:"id"`
	Flag string `json:"flag"`
}

// RemoveAnswerFlag is guarded the same way AddAnswerFlag is (F11): without the
// ANY(flags) check, aggregation's per-answer "clear all agg_* flags, re-add
// raised" loop (grading/aggregate_run.go) rewrites every answer row 3x per
// pass even when nothing changed, stamping a fresh updated_at each time. The
// guard makes the UPDATE match zero rows when the flag was never present.
func (q *Queries) RemoveAnswerFlag(ctx context.Context, arg RemoveAnswerFlagParams) error {
	_, err := q.db.Exec(ctx, removeAnswerFlag, arg.ID, arg.Flag)
	return err
}

